describe('Sauce Demo Mobile Responsiveness', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display inventory page and burger menu on mobile viewport', () => {
    cy.viewport(375, 860);
    cy.get('[data-testid="user-name-input"]').type('standard_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/inventory.');
    cy.get('[data-testid="inventory-page"]').should('be.visible');
    cy.get('[data-testid="inventory-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="burger-menu-btn"]').should('be.visible');
    cy.get('[data-testid="burger-menu-btn"]').should('have.attr', 'aria-expanded', 'false');
  });

  it('should open burger menu and display logout link on mobile viewport', () => {
    cy.viewport(375, 860);
    cy.get('[data-testid="user-name-input"]').type('standard_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="burger-menu-btn"]').click();
    cy.get('[data-testid="burger-menu-btn"]').should('have.attr', 'aria-expanded', 'true');
    cy.get('[data-testid="bm-menu"]').should('be.visible');
    cy.get('[data-testid="logout_sidebar_link"]').should('be.visible');
    cy.get('[data-testid="logout_sidebar-link"]').should('contain', 'Logout');
  });
});
